const script=root.document?.currentScript?.src;
if(typeof VOCAB!=='undefined'&&typeof add==='function'){
 const existing=new Map(VOCAB.filter(v=>v.lang==='de').map(v=>[v.level+'\n'+v.w,v]));
 for(const row of rows){const key=row.level+'\n'+row.de;let card=existing.get(key);if(!card){add('de',row.level,'Kalıp Cümleler',row.de,row.tr,'Satz',row.de,row.tr);card=VOCAB[VOCAB.length-1];existing.set(key,card);}card.cat='Kalıp Cümleler';card.phraseId=row.id;card.phraseTopic=row.topic;card.tr=row.tr;card.ex=row.de;card.exTr=row.tr;card.translations??={};card.translations.tr=row.tr;card.exampleTranslations=card.translations;byID.set(row.id,card);}
}
function nativeLang(language){return language==='de'?'en':language||'tr';}
function apply(pack){for(const row of rows){const card=byID.get(row.id);if(card)card.translations[pack.language]=pack.meanings[row.id];}}
async function ready(language){const lang=nativeLang(language);if(lang==='tr')return;if(!['en','ar','fr','es','ru'].includes(lang))throw Error('phrase_language');if(packs.has(lang))return;if(pending.has(lang))return pending.get(lang);
 const request=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const url=new URL('phrase-translations/'+lang+'.json?v=1.11.0',script||root.location.href),response=await root.fetch(url,{signal:controller.signal});if(!response.ok)throw Error('phrase_load');const pack=await response.json();if(pack.version!=='1.11.0'||pack.language!==lang||rows.some(r=>typeof pack.meanings?.[r.id]!=='string'||!pack.meanings[r.id].trim())||Object.keys(trGloss).some(k=>typeof pack.glosses?.[k]!=='string'||!pack.glosses[k].trim()))throw Error('phrase_data');packs.set(lang,pack);apply(pack);}finally{clearTimeout(timer);pending.delete(lang);}})();pending.set(lang,request);return request;
}
function meaning(row,language){const lang=nativeLang(language);return lang==='tr'?row.tr:packs.get(lang)?.meanings[row.id]||'';}
function gloss(row,language){const lang=nativeLang(language),map=lang==='tr'?trGloss:packs.get(lang)?.glosses;return(row.chunks||[]).map(([source,key])=>[source,map?.[key]||'']);}
root.LUMIRA_PHRASES={rows,ready,meaning,gloss};
